import React, { useState } from "react";

function RegisterForm({ onRegisterSuccess, goToLogin }) {
  const [mobile, setMobile] = useState("");
  const [name, setName] = useState("");
  const [password, setPassword] = useState("");
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [loading, setLoading] = useState(false);

  const sendOtp = async () => {
    setError("");
    setSuccess("");
    try {
      const res = await fetch("http://localhost:8080/api/otp/send", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mobile }),
      });
      if (!res.ok) throw new Error("Failed to send OTP");
      setOtpSent(true);
      setSuccess("✅ OTP sent successfully. Please enter it to continue.");
    } catch (err) {
      setError(err.message);
    }
  };

  const verifyAndRegister = async () => {
    setError("");
    setSuccess("");
    setLoading(true);
    try {
      const res = await fetch("http://localhost:8080/api/otp/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, mobile, password, otp }),
      });
      if (!res.ok) {
        const errMsg = await res.text();
        throw new Error(errMsg || "Registration failed");
      }
      setSuccess("✅ Registration successful. Please login.");
      setTimeout(() => onRegisterSuccess(), 1500);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          otpSent ? verifyAndRegister() : sendOtp();
        }}
        style={styles.form}
      >
        <h1 style={styles.title}>Create Account</h1>
        <p style={styles.subtitle}>Register with OTP verification</p>

        <input
          type="text"
          placeholder="Full Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
          style={styles.input}
        />

        <input
          type="tel"
          placeholder="Mobile Number"
          value={mobile}
          onChange={(e) => setMobile(e.target.value)}
          required
          style={styles.input}
        />

        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          style={styles.input}
        />

        {otpSent && (
          <input
            type="text"
            placeholder="Enter OTP"
            value={otp}
            onChange={(e) => setOtp(e.target.value)}
            required
            style={styles.input}
          />
        )}

        <button type="submit" style={styles.button} disabled={loading}>
          {loading
            ? "Processing..."
            : otpSent
            ? "Verify & Register"
            : "Send OTP"}
        </button>

        {error && <p style={styles.error}>{error}</p>}
        {success && <p style={styles.success}>{success}</p>}

        <p style={styles.switchText}>
          Already have an account? {" "}
          <span onClick={goToLogin} style={styles.link}>
            Login here
          </span>
        </p>
      </form>
    </div>
  );
}

const styles = {
  container: {
    minHeight: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "#f7f9fc",
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    padding: "20px",
  },
  form: {
    backgroundColor: "#ffffff",
    padding: "36px",
    borderRadius: "18px",
    boxShadow: "0 8px 30px rgba(0, 0, 0, 0.1)",
    maxWidth: "420px",
    width: "100%",
  },
  title: {
    fontSize: "28px",
    marginBottom: "8px",
    fontWeight: "700",
    color: "#111",
    textAlign: "center",
  },
  subtitle: {
    fontSize: "14px",
    marginBottom: "24px",
    textAlign: "center",
    color: "#666",
  },
  input: {
    width: "100%",
    padding: "14px",
    marginBottom: "16px",
    borderRadius: "8px",
    border: "1px solid #ddd",
    fontSize: "15px",
  },
  button: {
    width: "100%",
    padding: "14px",
    backgroundColor: "#007bff",
    color: "white",
    fontWeight: "600",
    border: "none",
    borderRadius: "8px",
    fontSize: "16px",
    cursor: "pointer",
  },
  error: {
    marginTop: "16px",
    color: "#dc3545",
    textAlign: "center",
    fontSize: "14px",
  },
  success: {
    marginTop: "16px",
    color: "#28a745",
    textAlign: "center",
    fontSize: "14px",
  },
  switchText: {
    marginTop: "20px",
    fontSize: "14px",
    textAlign: "center",
    color: "#555",
  },
  link: {
    color: "#007bff",
    cursor: "pointer",
    fontWeight: "600",
    textDecoration: "underline",
    marginLeft: "5px",
  },
};

export default RegisterForm;
